import React from "react";
import { useNavigate } from "react-router-dom";
import {
  FaJava,
  FaPython,
  FaDatabase,
  FaChartLine,
  FaLaptopCode
} from "react-icons/fa";

const Hero = () => {
  const navigate = useNavigate();

  const icons = [
    { icon: <FaJava />, angle: 0 },
    { icon: <FaPython />, angle: 72 },
    { icon: <FaDatabase />, angle: 144 },
    { icon: <FaChartLine />, angle: 216 },
    { icon: <FaLaptopCode />, angle: 288 }
  ];

  return (
    <section className="hero">
      <div className="container">

        {/* LEFT */}
        <div className="left">
          <p className="tag">WELCOME</p>

          <h1>I'm <span className="name">Swetha A</span></h1>

          <h2 className="role">
            Full Stack Developer • System Builder • UI Thinker
          </h2>

          <p className="desc">
            I design structured systems and build meaningful applications where logic, design, and performance work together.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>
            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>
        </div>

        {/* RIGHT */}
        <div className="right">
          <div className="radar">

            {/* center image */}
            <div className="center">
              <img
                src="/mnt/data/c5ecd2da-7d60-41b1-b2fb-f57293b5f438.png"
                alt="center"
              />
            </div>

            {/* orbit ring */}
            <div className="orbit-ring">
              {icons.map((item, i) => (
                <div
                  key={i}
                  className="orbit-item"
                  style={{
                    transform: `rotate(${item.angle}deg) translate(150px) rotate(-${item.angle}deg)`
                  }}
                >
                  <div className="icon">{item.icon}</div>
                </div>
              ))}
            </div>

          </div>
        </div>

      </div>

      <style>{`

      .hero {
        min-height: 100vh;
        display: flex;
        align-items: center;
        background: radial-gradient(circle at top, #0b1220, #050816);
        padding: 0 6%;
      }

      .container {
        display: grid;
        grid-template-columns: 1.3fr 1fr;
        align-items: center;
        width: 100%;
      }

      /* LEFT */
      .tag { color: #64748b; letter-spacing: 3px; font-size: 12px; }

      h1 { font-size: 60px; color: white; }

      .name { color: #38BDF8; }

      .role { color: #94a3b8; font-size: 18px; }

      .desc { color: #cbd5e1; max-width: 500px; margin-top: 15px; }

      .buttons { margin-top: 25px; display: flex; gap: 15px; }

      .btn {
        padding: 12px 20px;
        border-radius: 10px;
        border: 1px solid #38BDF8;
        cursor: pointer;
      }

      .primary { background: #38BDF8; color: black; }
      .secondary { background: transparent; color: #38BDF8; }

      /* RADAR */
      .radar {
        position: relative;
        width: 420px;
        height: 420px;
        margin: auto;
      }

      /* CENTER IMAGE */
      .center {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        z-index: 10;
      }

      .center img {
        width: 150px;
        border-radius: 20px;
        filter: drop-shadow(0 0 20px #38BDF8);
      }

      /* ORBIT SYSTEM */
      .orbit-ring {
        position: absolute;
        width: 100%;
        height: 100%;
        animation: spin 14s linear infinite;
      }

      .orbit-item {
        position: absolute;
        top: 50%;
        left: 50%;
      }

      .icon {
        width: 55px;
        height: 55px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        background: rgba(255,255,255,0.08);
        border: 1px solid rgba(56,189,248,0.4);
        box-shadow: 0 0 15px rgba(56,189,248,0.3);
        color: #38BDF8;
        font-size: 22px;
      }

      @keyframes spin {
        from { transform: rotate(0deg); }
        to { transform: rotate(360deg); }
      }

      `}</style>

    </section>
  );
};

export default Hero;
